/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Types: Exchange, FixtureFile, Probe
 *   Functions: pickHeaders, fetchProbe, record, musicBrainz, itunes, coverArt, lookupRelease, probes,
 *              writeFixtures, main
 *   Constants: userAgentProduct, userAgent, recordedHeaders, gate, recordedAt, files
 * @end-catalog */

/**
 * Re-records the trimmed public metadata-lookup fixtures under `test/fixtures/metadataLookup/`.
 * It contacts MusicBrainz, the Cover Art Archive and the iTunes Search API, so it runs only by hand:
 *   npm run record:metadata-lookup-fixtures -- --live
 * Tests and CI never run it. It sends a fixed recorder User-Agent and no credentials, never reads
 * `.env`, paces every source with the contract rates, records only public catalog metadata trimmed
 * by the clients' allowlisted shapes, and writes the new set only after every probe succeeded.
 */
import { randomUUID } from 'node:crypto';
import { existsSync } from 'node:fs';
import { cp, mkdir, readFile, readdir, rename, rm, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { setTimeout as delay } from 'node:timers/promises';
import { openPinnedHttps, readPinnedBody, requestPinnedHttps, type PinnedHttpsTransport } from '../src/administration/adminPinnedHttps';
import { METADATA_LOOKUP_LIMITS, type MetadataLookupSource } from '../src/administration/lookup/lookupContract';
import { createProcessLookupRateGate } from '../src/administration/lookup/lookupRateGate';
import { decodeLookupJson, validateLookupShape, type LookupShape } from '../src/administration/lookup/lookupResponseShape';
import { parseRetryAfter } from '../src/administration/lookup/lookupSourceRequest';
import {
    musicBrainzDestination, musicBrainzShapes, musicBrainzUrls, parseMusicBrainzBrowse, parseMusicBrainzIsrc,
    parseMusicBrainzRecordingSearch, parseMusicBrainzRelease, parseMusicBrainzReleaseSearch
} from '../src/administration/lookup/musicBrainzClient';
import { itunesDestination, itunesShape, itunesUrls, parseItunesResponse } from '../src/administration/lookup/iTunesSearchClient';
import { coverArtDestination, coverArtListingUrl, coverArtShape, parseCoverArtListing } from '../src/administration/lookup/coverArtClient';

const userAgentProduct = 'ArchtreeMetadataFixtureRecorder/0.1';
const userAgent = `${userAgentProduct} ( https://github.com/yangyinxu/Archtree )`;
const recordedHeaders = ['content-type', 'location', 'retry-after'] as const;

type Exchange = { url: string; status: number; headers: Record<string, string>; body?: unknown };
type FixtureFile = { source: MetadataLookupSource; recordedAt: string; description: string; exchanges: Exchange[] };
type Probe = {
    source: MetadataLookupSource; url: URL; destination: (url: URL, hop: number) => URL | null; shape: LookupShape;
    check: (json: unknown) => unknown; contentTypes: readonly string[]; maximumBytes: number; deadlineMs: number;
};

const gate = createProcessLookupRateGate();
const recordedAt = new Date().toISOString();
const files = new Map<string, FixtureFile>();

const pickHeaders = (headers: Record<string, unknown>) => {
    const picked: Record<string, string> = {};
    for (const name of recordedHeaders) if (typeof headers[name] === 'string') picked[name] = headers[name] as string;
    return picked;
};

/** One paced GET; every hop is captured, the 200 body is trimmed by the shape and re-parsed by the client parser. */
const fetchProbe = async (probe: Probe): Promise<{ status: number; trimmed: unknown; exchanges: Exchange[] }> => {
    for (let attempt = 0; attempt < 3; attempt++) {
        const lease = await gate.acquire(probe.source, 'wait', new AbortController().signal);
        const exchanges: Exchange[] = [];
        const transport: PinnedHttpsTransport = {
            request: async (url, address, signal, headers) => {
                const response = await requestPinnedHttps(url, address, signal, headers);
                exchanges.push({ url: url.href, status: response.statusCode, headers: pickHeaders(response.headers as Record<string, unknown>) });
                return response;
            }
        };
        let backoffMs: number | undefined;
        try {
            const deadline = AbortSignal.timeout(probe.deadlineMs);
            let opened;
            try {
                opened = await openPinnedHttps(probe.url, deadline, {
                    destination: probe.destination, headers: { Accept: 'application/json', 'User-Agent': userAgent },
                    maximumRedirects: METADATA_LOOKUP_LIMITS.maximumRedirects, failure: () => new Error(`request failed: ${probe.url.href}`)
                }, transport);
            } catch (error) {
                // A transient DNS or connection failure is retried like a 503, within the same bound.
                if (attempt === 2) throw error;
                backoffMs = 3000;
                console.warn(`${probe.source} request failed; retrying in ${backoffMs} ms`);
                continue;
            }
            const { response } = opened;
            const last = exchanges[exchanges.length - 1];
            if (response.statusCode === 200) {
                const type = String(response.headers['content-type'] ?? '').split(';')[0].trim().toLowerCase();
                if (!probe.contentTypes.includes(type)) { response.body.destroy(); throw new Error(`unexpected content type ${type}: ${probe.url.href}`); }
                const body = await readPinnedBody(response, deadline, probe.maximumBytes, () => new Error(`body failed: ${probe.url.href}`));
                const trimmed = validateLookupShape(probe.shape, decodeLookupJson(body));
                probe.check(JSON.parse(JSON.stringify(trimmed)));
                last.body = trimmed;
                return { status: 200, trimmed, exchanges };
            }
            response.body.destroy();
            if (response.statusCode === 404) return { status: 404, trimmed: null, exchanges };
            if (response.statusCode !== 503 && response.statusCode !== 429) throw new Error(`unexpected status ${response.statusCode}: ${probe.url.href}`);
            backoffMs = parseRetryAfter(response.headers['retry-after'], Date.now()) ?? 5000;
            console.warn(`${probe.source} answered ${response.statusCode}; waiting ${backoffMs} ms`);
        } finally { await lease.release(backoffMs === undefined ? undefined : { backoffMs }); }
        await delay(backoffMs);
    }
    throw new Error(`still rate limited after retries: ${probe.url.href}`);
};

const record = async (file: string, description: string, probe: Probe) => {
    const result = await fetchProbe(probe);
    files.set(file, { source: probe.source, recordedAt, description, exchanges: result.exchanges });
    console.log(`${result.status} ${file}`);
    return result;
};

const musicBrainz = (url: URL, shape: LookupShape, check: (json: unknown) => unknown): Probe => ({
    source: 'musicbrainz', url, destination: musicBrainzDestination, shape, check, contentTypes: ['application/json'],
    maximumBytes: METADATA_LOOKUP_LIMITS.musicBrainzBytes, deadlineMs: METADATA_LOOKUP_LIMITS.requestDeadlineMs.musicbrainz
});
const itunes = (url: URL): Probe => ({
    source: 'itunes', url, destination: itunesDestination, shape: itunesShape, check: parseItunesResponse,
    contentTypes: ['application/json', 'text/javascript'], maximumBytes: METADATA_LOOKUP_LIMITS.itunesBytes,
    deadlineMs: METADATA_LOOKUP_LIMITS.requestDeadlineMs.itunes
});
const coverArt = (releaseId: string): Probe => ({
    source: 'coverartarchive', url: coverArtListingUrl(releaseId), destination: coverArtDestination(releaseId), shape: coverArtShape,
    check: json => parseCoverArtListing(json, releaseId), contentTypes: ['application/json'],
    maximumBytes: METADATA_LOOKUP_LIMITS.coverArtBytes, deadlineMs: METADATA_LOOKUP_LIMITS.requestDeadlineMs.coverartarchive
});
const lookupRelease = async (releaseId: string, why: string) => {
    const result = await record(`musicbrainz/release-${releaseId}.json`, `MusicBrainz release lookup (${why})`,
        musicBrainz(musicBrainzUrls.release(releaseId), musicBrainzShapes.release, parseMusicBrainzRelease));
    return result.status === 200 ? parseMusicBrainzRelease(result.trimmed) : null;
};

const probes = async () => {
    // Hotel California / Eagles: many 9-track editions on different labels, plus longer and shorter editions.
    const hotel = await record('musicbrainz/release-search-hotel-california.json', 'Release search: release "Hotel California" AND artist "Eagles"',
        musicBrainz(musicBrainzUrls.releaseSearch({ release: 'Hotel California', artist: 'Eagles' }), musicBrainzShapes.releaseSearch, parseMusicBrainzReleaseSearch));
    for (const release of parseMusicBrainzReleaseSearch(hotel.trimmed).releases.slice(0, 25)) await lookupRelease(release.releaseId, 'Hotel California search result');
    await record('musicbrainz/browse-release-group-836f349a.json', 'Release-group browse: Hotel California',
        musicBrainz(musicBrainzUrls.releaseGroupBrowse('836f349a-0434-3e8b-a0bc-261f77a9f99c'), musicBrainzShapes.browse, parseMusicBrainzBrowse));

    // Blue Archive Original Soundtrack Vol.1: JP CD and JP digital editions, plus the Korean anniversary edition.
    const credited = await record('musicbrainz/release-search-blue-archive-credited.json', 'Release search with the credited names and the ~ subtitle',
        musicBrainz(musicBrainzUrls.releaseSearch({ release: 'Blue Archive Original Soundtrack Vol.1 ~Longing for the memorable days~', artist: 'Mitsukiyo、KARUT、Nor' }),
            musicBrainzShapes.releaseSearch, parseMusicBrainzReleaseSearch));
    const titled = await record('musicbrainz/release-search-blue-archive-title.json', 'Release search by title only',
        musicBrainz(musicBrainzUrls.releaseSearch({ release: 'Blue Archive Original Soundtrack Vol.1' }), musicBrainzShapes.releaseSearch, parseMusicBrainzReleaseSearch));
    const blueArchive = new Set([...parseMusicBrainzReleaseSearch(credited.trimmed).releases, ...parseMusicBrainzReleaseSearch(titled.trimmed).releases]
        .map(release => release.releaseId));
    blueArchive.add('85bc0ffc-7c17-42f1-a526-354a6ec6fadd');
    for (const releaseId of blueArchive) if (!files.has(`musicbrainz/release-${releaseId}.json`)) await lookupRelease(releaseId, 'Blue Archive search result');

    // パンドラコール / ヰ世界情緒: one song on singles, albums, a live album and a CD+Blu-ray edition.
    const pandora = await record('musicbrainz/recording-search-pandora-call.json', 'Recording search: recording "パンドラコール" AND artist "ヰ世界情緒"',
        musicBrainz(musicBrainzUrls.recordingSearch({ recording: 'パンドラコール', artist: 'ヰ世界情緒' }), musicBrainzShapes.recordingSearch, parseMusicBrainzRecordingSearch));
    const pandoraReleases = [...new Set(parseMusicBrainzRecordingSearch(pandora.trimmed).recordings.flatMap(hit => hit.releases.map(release => release.releaseId)))].sort();
    const lookedUp = [];
    for (const releaseId of pandoraReleases) if (!files.has(`musicbrainz/release-${releaseId}.json`)) lookedUp.push(await lookupRelease(releaseId, 'Pandora Call recording search result'));
    const single = lookedUp.find(release => release?.releaseId.startsWith('8659aff4'));
    const isrc = single?.media[0]?.tracks[0]?.isrcs[0];
    if (isrc) await record(`musicbrainz/isrc-${isrc}.json`, 'ISRC lookup of the Pandora Call single recording',
        musicBrainz(musicBrainzUrls.isrc(isrc), musicBrainzShapes.isrc, parseMusicBrainzIsrc));

    await record('itunes/search-us-album-hotel-california.json', 'iTunes album search (us): Hotel California Eagles', itunes(itunesUrls.search('Hotel California Eagles', 'us', 'album')));
    const songs = await record('itunes/search-jp-song-pandora-call.json', 'iTunes song search (jp): パンドラコール', itunes(itunesUrls.search('パンドラコール', 'jp', 'song')));
    const track = parseItunesResponse(songs.trimmed).tracks.find(item => item.artistName === 'ヰ世界情緒' && item.collectionName?.startsWith('パンドラコール'));
    if (!track) throw new Error('the Pandora Call single was not found in the iTunes song search');
    await record(`itunes/lookup-jp-${track.collectionId}.json`, 'iTunes collection lookup (jp) of the Pandora Call single', itunes(itunesUrls.lookupId(track.collectionId, 'jp')));
    await record('itunes/lookup-us-upc-075596050920.json', 'iTunes UPC lookup (us) of the Hotel California barcode', itunes(itunesUrls.lookupUpc('075596050920', 'us')));
    await record('itunes/search-jp-song-pandora-call-romanized.json', 'iTunes song search (jp): Pandora Call', itunes(itunesUrls.search('Pandora Call', 'jp', 'song')));

    if (!single) throw new Error('the Pandora Call single 8659aff4 was not found');
    for (const [releaseId, why] of [['83afdb26-9c27-4ec6-ad70-25b8cb897a31', 'Hotel California, front artwork'],
        ['8baecda4-f155-40f6-a173-8f6b98cede5b', 'Blue Archive JP CD'], [single.releaseId, 'Pandora Call single'],
        ['24ae881f-7cb3-4c43-b80e-70332cd7c50d', 'Hotel California without artwork (404)']] as const) {
        await record(`coverartarchive/listing-${releaseId}.json`, `Cover Art Archive listing: ${why}`, coverArt(releaseId));
    }
};

/**
 * Builds the complete new set beside the old one, keeps hand-written synthetic samples, then swaps
 * directories. If the swap fails (for example Windows EPERM while a file is open), the old set is put
 * back and the complete new set is kept and reported, so no second live run is needed.
 */
const writeFixtures = async (root: string) => {
    const staging = `${root}.recording-${randomUUID()}`, previous = `${root}.previous-${randomUUID()}`;
    await mkdir(staging, { recursive: true });
    let built = false, moved = false;
    try {
        for (const source of ['musicbrainz', 'itunes', 'coverartarchive']) {
            await mkdir(path.join(staging, source), { recursive: true });
            const existing = path.join(root, source);
            if (!existsSync(existing)) continue;
            for (const name of await readdir(existing)) {
                const json = JSON.parse(await readFile(path.join(existing, name), 'utf8'));
                if (json?.synthetic === true) await cp(path.join(existing, name), path.join(staging, source, name));
            }
        }
        for (const [file, content] of [...files.entries()].sort(([left], [right]) => left < right ? -1 : 1)) {
            await writeFile(path.join(staging, file), `${JSON.stringify(content, null, 2)}\n`, 'utf8');
        }
        await writeFile(path.join(staging, 'manifest.json'), `${JSON.stringify({
            recorder: 'scripts/record-metadata-lookup-fixtures.ts', recordedAt, userAgentProduct,
            probes: [...files.entries()].sort(([left], [right]) => left < right ? -1 : 1).map(([file, content]) => ({ file, description: content.description }))
        }, null, 2)}\n`, 'utf8');
        built = true;
        if (existsSync(root)) { await rename(root, previous); moved = true; }
        await rename(staging, root);
    } catch (error) {
        if (moved && !existsSync(root)) await rename(previous, root).catch(() => console.error(`The previous fixtures are at ${previous}`));
        if (built) console.error(`The new fixtures are kept at ${staging}`);
        else await rm(staging, { recursive: true, force: true });
        throw error;
    }
    if (moved) await rm(previous, { recursive: true, force: true }).catch(() => console.warn(`Remove the previous fixtures at ${previous}`));
};

const main = async () => {
    if (!process.argv.includes('--live') || process.env.NODE_TEST_CONTEXT !== undefined) {
        console.error('Refusing to contact live services: pass --live, and never run this from a test.');
        process.exit(2);
    }
    const repository = process.cwd();
    const manifest = JSON.parse(await readFile(path.join(repository, 'package.json'), 'utf8'));
    if (manifest.name !== 'archtree') throw new Error('Run this from the Archtree repository root.');
    await probes();
    await writeFixtures(path.join(repository, 'test', 'fixtures', 'metadataLookup'));
    console.log(`Recorded ${files.size} fixture files.`);
};

main().catch(error => {
    console.error(error instanceof Error ? error.message : 'Recording failed.');
    process.exitCode = 1;
});
